    <script>
    // CHIP-8 Emulator
    class Chip8 {
        constructor() {
            this.memory = new Uint8Array(4096);
            this.v = new Uint8Array(16);
            this.i = 0;
            this.pc = 0x200;
            this.stack = [];
            this.sp = 0;
            this.delayTimer = 0;
            this.soundTimer = 0;
            this.key = new Uint8Array(16);
            this.display = new Uint8Array(64 * 32);
            this.paused = true;
            this.speed = 10;
            this.lastFrameTime = 0;
            this.rom = null;

            // Load font set
            this.loadFontSet();
        }

        loadFontSet() {
            const fontSet = [
                0xF0, 0x90, 0x90, 0x90, 0xF0,
                0x20, 0x60, 0x20, 0x20, 0x70,
                0xF0, 0x10, 0xF0, 0x80, 0xF0,
                0xF0, 0x10, 0xF0, 0x10, 0xF0,
                0x90, 0x90, 0xF0, 0x10, 0x10,
                0xF0, 0x80, 0xF0, 0x10, 0xF0,
                0xF0, 0x90, 0x90, 0x90, 0xF0,
                0x10, 0x20, 0x40, 0x20, 0x10,
                0xF0, 0x90, 0xF0, 0x90, 0xF0,
                0x90, 0x90, 0xF0, 0x10, 0xF0,
                0xF0, 0x90, 0xF0, 0x10, 0xF0,
                0xF0, 0x90, 0xF0, 0x90, 0x90,
                0xE0, 0x90, 0xE0, 0x90, 0xE0,
                0xF0, 0x80, 0x80, 0x80, 0xF0,
                0xE0, 0x90, 0x90, 0x90, 0xE0,
                0xF0, 0x80, 0xF0, 0x80, 0xF0,
                0xF0, 0x80, 0xF0, 0x80, 0x80
            ];

            for (let i = 0; i < fontSet.length; i++) {
                this.memory[0x050 + i] = fontSet[i];
            }
        }

        loadROM(data) {
            const bytes = new Uint8Array(data);
            for (let i = 0; i < bytes.length && i < 0x200 - 0x200; i++) {
                this.memory[0x200 + i] = bytes[i];
            }
            this.pc = 0x200;
            this.sp = 0;
            this.stack = [];
            this.delayTimer = 0;
            this.soundTimer = 0;
            this.display.fill(0);
            this.v.fill(0);
            this.paused = true;
            this.rom = data;
        }

        reset() {
            this.pc = 0x200;
            this.sp = 0;
            this.stack = [];
            this.delayTimer = 0;
            this.soundTimer = 0;
            this.display.fill(0);
            this.v.fill(0);
            this.paused = true;
        }

        loadKey(key, pressed) {
            const keyMap = {
                '1': 0x1, '2': 0x2, '3': 0x3, 'C': 0xC,
                '4': 0x4, '5': 0x5, '6': 0x6, 'D': 0xD,
                '7': 0x7, '8': 0x8, '9': 0x9, 'E': 0xE,
                'A': 0xA, '0': 0x0, 'B': 0xB, 'F': 0xF
            };
            if (key in keyMap) {
                this.key[keyMap[key]] = pressed ? 1 : 0;
            }
        }

        updateTimers() {
            if (this.delayTimer > 0) this.delayTimer--;
            if (this.soundTimer > 0) this.soundTimer--;
        }

        drawSprite(x, y, height, sprite) {
            let collision = 0;
            const screenX = x % 64;
            const screenY = y % 32;

            for (let row = 0; row < height; row++) {
                const spriteByte = sprite[row];
                const drawY = (screenY + row) % 32;

                for (let col = 0; col < 8; col++) {
                    const drawX = (screenX + col) % 64;
                    const pixel = (spriteByte & (0x80 >> col)) !== 0;
                    const index = drawY * 64 + drawX;
                    const oldPixel = this.display[index];

                    if (pixel) {
                        this.display[index] ^= 1;
                        if (this.display[index] === 1) collision = 1;
                    }

                    if (oldPixel !== this.display[index]) {
                        collision = 1;
                    }
                }
            }

            this.v[0xF] = collision;
        }

        fetchDecodeExecute() {
            if (this.pc >= 4096) {
                this.pc = 0x200;
                return;
            }

            const opcode = (this.memory[this.pc] << 8) | this.memory[this.pc + 1];
            this.pc += 2;

            const nnn = opcode & 0x0FFF;
            const nn = opcode & 0x00FF;
            const n = opcode & 0x000F;
            const x = (opcode >> 8) & 0x000F;
            const y = (opcode >> 4) & 0x000F;

            switch (opcode & 0xF000) {
                // 0NNN: Clear display
                case 0x0000:
                    if (nnn === 0x0E0) {
                        this.display.fill(0);
                    } else if (nnn === 0x0EE) {
                        this.sp--;
                        this.pc = this.stack[this.sp];
                    }
                    break;

                // 1NNN: Jump to address
                case 0x1000:
                    this.pc = nnn;
                    break;

                // 2NNN: Call subroutine
                case 0x2000:
                    if (this.sp < 16) {
                        this.stack[this.sp++] = this.pc;
                        this.pc = nnn;
                    }
                    break;

                // 3XNN: Skip if VX == NN
                case 0x3000:
                    if (this.v[x] === nn) this.pc += 2;
                    break;

                // 4XNN: Skip if VX != NN
                case 0x4000:
                    if (this.v[x] !== nn) this.pc += 2;
                    break;

                // 5XY0: Skip if VX == VY
                case 0x5000:
                    if (this.v[x] === this.v[y]) this.pc += 2;
                    break;

                // 6XNN: Set VX = NN
                case 0x6000:
                    this.v[x] = nn;
                    break;

                // 7XNN: Set VX = VX + NN
                case 0x7000:
                    this.v[x] = (this.v[x] + nn) & 0xFF;
                    break;

                // 8XY0: Set VX = VY
                case 0x8000:
                    if (n === 0) {
                        this.v[x] = this.v[y];
                    } else if (n === 1) {
                        this.v[x] = this.v[x] | this.v[y];
                    } else if (n === 2) {
                        this.v[x] = (this.v[x] + this.v[y]) & 0xFF;
                    } else if (n === 3) {
                        this.v[x] = this.v[x] ^ this.v[y];
                    } else if (n === 4) {
                        const sum = this.v[x] + this.v[y];
                        this.v[0xF] = sum > 0xFF ? 1 : 0;
                        this.v[x] = sum & 0xFF;
                    } else if (n === 5) {
                        const diff = this.v[x] - this.v[y];
                        this.v[0xF] = this.v[x] > this.v[y] ? 1 : 0;
                        this.v[x] = diff & 0xFF;
                    } else if (n === 6) {
                        this.v[0xF] = this.v[x] & 1;
                        this.v[x] = (this.v[x] >> 1);
                    } else if (n === 7) {
                        const diff = this.v[y] - this.v[x];
                        this.v[0xF] = this.v[y] > this.v[x] ? 1 : 0;
                        this.v[x] = diff & 0xFF;
                    } else if (n === 0xE) {
                        this.v[0xF] = (this.v[x] >> 7) & 1;
                        this.v[x] = (this.v[x] << 1);
                    }
                    break;

                // 9XY0: Skip if VX != VY
                case 0x9000:
                    if (this.v[x] !== this.v[y]) this.pc += 2;
                    break;

                // ANNN: Set I = NNN
                case 0xA000:
                    this.i = nnn;
                    break;

                // BNNN: Jump to V0 + NNN
                case 0xB000:
                    this.pc = this.v[0] + nnn;
                    break;

                // CXNN: Set VX = (rand() % NN) & VF
                case 0xC000:
                    this.v[x] = (Math.floor(Math.random() * 256) % nn) & 0xFF;
                    break;

                // DXYN: Draw sprite
                case 0xD000: {
                    const sprite = [];
                    for (let k = 0; k < n; k++) {
                        sprite.push(this.memory[this.i + k]);
                    }
                    this.drawSprite(this.v[x], this.v[y], n, sprite);
                    break;
                }

                // EX9E: Skip if VX = key
                case 0xE000:
                    if (n === 0x9E) {
                        if (this.v[x] !== 0 && this.key[this.v[x]]) this.pc += 2;
                    } else if (n === 0xA1) {
                        if (this.v[x] !== 0 && !this.key[this.v[x]]) this.pc += 2;
                    }
                    break;

                // FX07: Set VX = delay timer
                case 0xF000:
                    if (nn === 0x07) {
                        this.v[x] = this.delayTimer;
                    } else if (nn === 0x0A) {
                        this.paused = true;
                        this.waitKey = x;
                    } else if (nn === 0x15) {
                        this.delayTimer = this.v[x];
                    } else if (nn === 0x18) {
                        this.soundTimer = this.v[x];
                    } else if (nn === 0x1E) {
                        this.i = (this.i + this.v[x]) & 0xFFF;
                    } else if (nn === 0x29) {
                        this.i = this.v[x] * 5;
                    } else if (nn === 0x33) {
                        this.memory[this.i] = Math.floor(this.v[x] / 100);
                        this.memory[this.i + 1] = Math.floor((this.v[x] % 100) / 10);
                        this.memory[this.i + 2] = this.v[x] % 10;
                    } else if (nn === 0x55) {
                        for (let k = 0; k <= x; k++) {
                            this.memory[this.i + k] = this.v[k];
                        }
                    } else if (nn === 0x65) {
                        for (let k = 0; k <= x; k++) {
                            this.v[k] = this.memory[this.i + k];
                        }
                    }
                    break;
            }
        }

        run() {
            this.paused = false;
            this.lastFrameTime = performance.now();
        }

        pause() {
            this.paused = true;
        }

        step() {
            this.paused = true;
            this.fetchDecodeExecute();
        }

        execute() {
            if (this.paused) return;
            const now = performance.now();
            const elapsed = now - this.lastFrameTime;
            const interval = 1000 / (60 * this.speed);

            if (elapsed >= interval) {
                this.updateTimers();
                for (let i = 0; i < this.speed; i++) {
                    this.fetchDecodeExecute();
                    if (this.paused) break;
                }
                this.lastFrameTime = now;
            }
        }

        getRegisters() {
            return {
                pc: this.pc,
                i: this.i,
                delay: this.delayTimer,
                sound: this.soundTimer,
                sp: this.sp,
                vf: this.v[0xF],
                v: Array.from(this.v)
            };
        }

        getCurrentInstruction() {
            if (this.pc >= 4096) return { mnemonic: 'STOP', operands: '' };
            const opcode = (this.memory[this.pc] << 8) | this.memory[this.pc + 1];
            return this.decodeInstruction(opcode);
        }

        decodeInstruction(opcode) {
            const nnn = opcode & 0x0FFF;
            const nn = opcode & 0x00FF;
            const n = opcode & 0x000F;
            const x = (opcode >> 8) & 0x000F;
            const y = (opcode >> 4) & 0x000F;

            const ops = {
                '0x0NNN': `SYS ${nnn.toString(16).toUpperCase().padStart(3, '0')}`,
                '0x00E0': 'CLS',
                '0x00EE': 'RET',
                '0x1NNN': `JP ${nnn.toString(16).toUpperCase().padStart(3, '0')}`,
                '0x2NNN': `CALL ${nnn.toString(16).toUpperCase().padStart(3, '0')}`,
                '0x3XNN': `SE V${x}, ${nn.toString(16).toUpperCase().padStart(2, '0')}`,
                '0x4XNN': `SNE V${x}, ${nn.toString(16).toUpperCase().padStart(2, '0')}`,
                '0x5XY0': `SE V${x}, V${y}`,
                '0x6XNN': `LD V${x}, ${nn.toString(16).toUpperCase().padStart(2, '0')}`,
                '0x7XNN': `ADD V${x}, ${nn.toString(16).toUpperCase().padStart(2, '0')}`,
                '0x8XY0': `LD V${x}, V${y}`,
                '0x8XY1': `OR V${x}, V${y}`,
                '0x8XY2': `AND V${x}, V${y}`,
                '0x8XY3': `XOR V${x}, V${y}`,
                '0x8XY4': `ADD V${x}, V${y}`,
                '0x8XY5': `SUB V${x}, V${y}`,
                '0x8XY6': `SHR V${x}`,
                '0x8XY7': `SUBN V${x}, V${y}`,
                '0x8XYE': `SHL V${x}`,
                '0x9XY0': `SNE V${x}, V${y}`,
                '0xANNN': `LD I, ${nnn.toString(16).toUpperCase().padStart(3, '0')}`,
                '0xBNNN': `JP V0, ${nnn.toString(16).toUpperCase().padStart(3, '0')}`,
                '0xCXNN': `RND V${x}, ${nn.toString(16).toUpperCase().padStart(2, '0')}`,
                '0xDXYN': `DRW V${x}, V${y}, ${n}`,
                '0xEX9E': `SKP V${x}`,
                '0xEXA1': `SKNP V${x}`,
                '0xFX07': `LD V${x}, DT`,
                '0xFX0A': `LD V${x}, K`,
                '0xFX15': `LD DT, V${x}`,
                '0xFX18': `LD ST, V${x}`,
                '0xFX1E': `ADD I, V${x}`,
                '0xFX29': `LD F, V${x}`,
                '0xFX33': `LD B, V${x}`,
                '0xFX55': `LD [I], V${x}`,
                '0xFX65': `LD V${x}, [I]}`,
            };

            return {
                opcode: opcode.toString(16).toUpperCase().padStart(4, '0'),
                mnemonic: ops[`0x${(opcode & 0xF000).toString(16).toUpperCase()}`] || 'UNKNOWN',
                operands: ops[`0x${(opcode & 0xF000).toString(16).toUpperCase()}`] || ''
            };
        }
    }

    // Demo ROM: Draw a sprite and react to key press
    const demoROM = new Uint8Array([
        0x12, 0x34, // SYS 01234 (skip)
        0x6A, 0x01, // LD V[0xA], 0x01
        0x6B, 0x02, // LD V[0xB], 0x02
        0x6C, 0x03, // LD V[0xC], 0x03
        0x6D, 0x04, // LD V[0xD], 0x04
        0xA00, 0x00, // LD I, 0x0000
        0x7A, 0x01, // ADD V[0xA], 0x01
        0x7B, 0x01, // ADD V[0xB], 0x01
        0x7C, 0x01, // ADD V[0xC], 0x01
        0x7D, 0x01, // ADD V[0xD], 0x01
        0x62, 0x10, // LD V[0x2], 0x10
        0xA00, 0x20, // LD I, 0x0020
        0xF1, 0x55, // LD [I], V[1]
        0x80, 0x04, // ADD V[0], V[4]
        0xD0, 0x10, // DRW V[0], V[0], 0x10
        0x60, 0x02, // LD V[0], 0x02
        0x80, 0x04, // ADD V[0], V[4]
        0xD0, 0x10, // DRW V[0], V[0], 0x10
        0x60, 0x01, // LD V[0], 0x01
        0x80, 0x04, // ADD V[0], V[4]
        0xD0, 0x10, // DRW V[0], V[0], 0x10
        0x60, 0x00, // LD V[0], 0x00
        0x80, 0x04, // ADD V[0], V[4]
        0xD0, 0x10, // DRW V[0], V[0], 0x10
        0x6A, 0x01, // LD V[0xA], 0x01
        0xF0, 0x0A, // LD V[0], K
        0x60, 0x00, // LD V[0], 0x00
        0x30, 0x0F, // SE V[0], 0x0F
        0x6A, 0x02, // LD V[0xA], 0x02
        0x60, 0x00, // LD V[0], 0x00
        0x30, 0x0F, // SE V[0], 0x0F
        0x6A, 0x03, // LD V[0xA], 0x03
        0x60, 0x00, // LD V[0], 0x00
        0x30, 0x0F, // SE V[0], 0x0F
        0x6A, 0x04, // LD V[0xA], 0x04
        0x60, 0x00, // LD V[0], 0x00
        0x30, 0x0F, // SE V[0], 0x0F
        0x6A, 0x01, // LD V[0xA], 0x01
        0x12, 0x34, // SYS 01234 (loop)
    ]);

    // UI
    const canvas = document.getElementById('display');
    const ctx = canvas.getContext('2d');
    const canvasScaled = document.createElement('canvas');
    const scaledWidth = 320;
    const scaledHeight = 160;
    canvasScaled.width = scaledWidth;
    canvasScaled.height = scaledHeight;
    const scaledCtx = canvasScaled.getContext('2d');

    function drawDisplay() {
        scaledCtx.fillStyle = '#000';
        scaledCtx.fillRect(0, 0, scaledWidth, scaledHeight);

        for (let y = 0; y < 32; y++) {
            for (let x = 0; x < 64; x++) {
                const index = y * 64 + x;
                if (chip8.display[index]) {
                    scaledCtx.fillStyle = '#4ec9b0';
                    scaledCtx.fillRect(x * (scaledWidth / 64), y * (scaledHeight / 32), Math.ceil(scaledWidth / 64), Math.ceil(scaledHeight / 32));
                }
            }
        }

        ctx.drawImage(canvasScaled, 0, 0);
    }

    function updateDebugger() {
        const regs = chip8.getRegisters();
        const instr = chip8.getCurrentInstruction();

        document.getElementById('debug-pc').textContent = '0x' + regs.pc.toString(16).toUpperCase().padStart(3, '0');
        document.getElementById('debug-i').textContent = '0x' + regs.i.toString(16).toUpperCase().padStart(3, '0');
        document.getElementById('debug-delay').textContent = regs.delay;
        document.getElementById('debug-sound').textContent = regs.sound;
        document.getElementById('debug-sp').textContent = regs.sp;
        document.getElementById('debug-vf').textContent = regs.vf;

        const instrEl = document.getElementById('debug-instruction');
        instrEl.innerHTML = `<span class="mnemonic">${instr.mnemonic}</span><span class="operands">${instr.operands}</span>`;

        const stackEl = document.getElementById('debug-stack');
        stackEl.innerHTML = '';
        for (let i = 0; i < regs.sp; i++) {
            const span = document.createElement('span');
            span.className = 'stack-item';
            span.textContent = '0x' + chip8.stack[i].toString(16).toUpperCase().padStart(3, '0');
            stackEl.appendChild(span);
        }
    }

    // Emulator
    const chip8 = new Chip8();
    chip8.loadROM(demoROM);

    // Controls
    document.getElementById('btn-run').addEventListener('click', () => chip8.run());
    document.getElementById('btn-pause').addEventListener('click', () => chip8.pause());
    document.getElementById('btn-step').addEventListener('click', () => chip8.step());
    document.getElementById('btn-reset').addEventListener('click', () => chip8.reset());
    document.getElementById('rom-input').addEventListener('change', (e) => {
        const file = e.target.files[0];
        if (file) {
            const reader = new FileReader();
            reader.onload = (event) => {
                chip8.loadROM(event.target.result);
            };
            reader.readAsArrayBuffer(file);
        }
    });

    document.getElementById('speed-slider').addEventListener('input', (e) => {
        chip8.speed = parseInt(e.target.value);
        document.getElementById('speed-value').textContent = chip8.speed;
    });

    // Keypad
    const keypad = document.getElementById('keypad');
    const keyMap = {
        '1': 0x1, '2': 0x2, '3': 0x3, 'C': 0xC,
        '4': 0x4, '5': 0x5, '6': 0x6, 'D': 0xD,
        '7': 0x7, '8': 0x8, '9': 0x9, 'E': 0xE,
        'A': 0xA, '0': 0x0, 'B': 0xB, 'F': 0xF
    };

    keypad.addEventListener('mousedown', (e) => {
        if (e.target.classList.contains('key')) {
            const key = e.target.dataset.key;
            e.target.classList.add('pressed');
            chip8.loadKey(key, true);
        }
    });

    keypad.addEventListener('mouseup', (e) => {
        if (e.target.classList.contains('key')) {
            const key = e.target.dataset.key;
            e.target.classList.remove('pressed');
            chip8.loadKey(key, false);
        }
    });

    keypad.addEventListener('mouseleave', (e) => {
        if (e.target.classList.contains('key')) {
            const key = e.target.dataset.key;
            e.target.classList.remove('pressed');
            chip8.loadKey(key, false);
        }
    });

    // Keyboard support
    document.addEventListener('keydown', (e) => {
        const key = e.key.toUpperCase();
        if (keyMap.hasOwnProperty(key)) {
            e.preventDefault();
            chip8.loadKey(key, true);
            const btn = document.querySelector(`.key[data-key="${key}"]`);
            if (btn) btn.classList.add('active');
        }
    });

    document.addEventListener('keyup', (e) => {
        const key = e.key.toUpperCase();
        if (keyMap.hasOwnProperty(key)) {
            chip8.loadKey(key, false);
            const btn = document.querySelector(`.key[data-key="${key}"]`);
            if (btn) btn.classList.remove('active');
        }
    });

    // Main loop
    function loop() {
        chip8.execute();
        drawDisplay();
        updateDebugger();
        requestAnimationFrame(loop);
    }

    loop();
    </script>
</body>
</html>"}

